/**
 * Animation Engine 테스트
 */

const AnimationEngine = require('./animation-engine');

let testsPassed = 0;
let testsFailed = 0;

function assertEqual(actual, expected, message) {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    console.error(`❌ ${message}`);
    console.error(`   Expected: ${JSON.stringify(expected)}`);
    console.error(`   Actual: ${JSON.stringify(actual)}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

function assertTrue(condition, message) {
  if (!condition) {
    console.error(`❌ ${message}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

console.log('\n╔════════════════════════════════════════════╗');
console.log('║  Animation Engine 테스트                  ║');
console.log('╚════════════════════════════════════════════╝\n');

// Test 1: @animation 블록 파싱
try {
  console.log('📝 Test 1: @animation 블록 파싱');
  const engine = new AnimationEngine();

  const block = `
    duration: 200ms
    timing: ease-out
    scale: 1 → 1.1
    blur: 0px → 5px
  `;

  const animation = engine.parseAnimation('hover', block);

  assertTrue(animation.name === 'hover', '애니메이션 이름');
  assertEqual(animation.duration, 200, '지속 시간');
  assertEqual(animation.timing, 'ease-out', '타이밍 함수');
  assertTrue(Object.keys(animation.properties).length > 0, '프로퍼티 파싱');

  console.log('✅ @animation 블록 파싱 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 2: CSS 키프레임 생성
try {
  console.log('📝 Test 2: CSS 키프레임 생성');
  const engine = new AnimationEngine();

  const block = `
    duration: 300ms
    scale: 1 → 0.95
  `;

  engine.parseAnimation('click', block);
  const keyframes = engine.generateAllKeyframes();

  assertTrue(keyframes.includes('@keyframes'), '@keyframes 포함');
  assertTrue(keyframes.includes('click'), 'click 애니메이션 포함');
  assertTrue(keyframes.includes('transform'), 'transform CSS 포함');

  console.log('✅ CSS 키프레임 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 3: 트리거 바인딩
try {
  console.log('📝 Test 3: 트리거 바인딩');
  const engine = new AnimationEngine();

  engine.parseAnimation('hover', 'duration: 200ms\nscale: 1 → 1.05');
  engine.bindTrigger('button', 'hover', 'hover');

  const stats = engine.getStats();
  assertEqual(stats.totalTriggers, 1, '트리거 카운트');

  console.log('✅ 트리거 바인딩 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 4: JavaScript 이벤트 핸들러 생성
try {
  console.log('📝 Test 4: JavaScript 이벤트 핸들러 생성');
  const engine = new AnimationEngine();

  engine.parseAnimation('fadeIn', `
    duration: 500ms
    opacity: 0 → 1
  `);

  const handler = engine.generateEventHandler('.box', 'mouseover', 'fadeIn');

  assertTrue(handler.includes('addEventListener'), 'addEventListener 포함');
  assertTrue(handler.includes('fadeIn'), 'fadeIn 애니메이션 참조');
  assertTrue(handler.includes('500ms'), '지속 시간 포함');

  console.log('✅ JavaScript 이벤트 핸들러 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 5: 화살표 표기법 (→) 처리
try {
  console.log('📝 Test 5: 화살표 표기법 (→) 처리');
  const engine = new AnimationEngine();

  const block = `
    duration: 400ms
    translate: 0 20px → 0 0
    opacity: 0 → 1
  `;

  engine.parseAnimation('slideUp', block);
  const keyframes = engine.generateAllKeyframes();

  assertTrue(keyframes.includes('0%'), '시작 상태');
  assertTrue(keyframes.includes('100%'), '종료 상태');
  assertTrue(keyframes.includes('0 0'), '변환된 좌표값');

  console.log('✅ 화살표 표기법 처리 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 6: 다중 애니메이션
try {
  console.log('📝 Test 6: 다중 애니메이션');
  const engine = new AnimationEngine();

  engine.parseAnimation('hover', 'duration: 200ms\nscale: 1 → 1.1');
  engine.parseAnimation('click', 'duration: 100ms\nscale: 1 → 0.95');
  engine.parseAnimation('fadeIn', 'duration: 500ms\nopacity: 0 → 1');

  const stats = engine.getStats();
  assertEqual(stats.totalAnimations, 3, '3개 애니메이션 등록');

  const handlers = engine.generateAllEventHandlers();
  console.log('✅ 다중 애니메이션 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

console.log('╔════════════════════════════════════════════╗');
console.log(`║  Test 결과: ${testsPassed}/6 통과               ║`);
console.log('╚════════════════════════════════════════════╝\n');

if (testsFailed === 0) {
  console.log('🎉 모든 테스트 통과!\n');
  process.exit(0);
} else {
  console.log(`❌ ${testsFailed}개 테스트 실패\n`);
  process.exit(1);
}
EOF
