/**
 * camelCase를 CSS 프로퍼티로 변환
 * @private
 */
_toCSSProperty(camelCase) {
  // transform 관련 프로퍼티들
  const transformProps = ['scale', 'rotate', 'rotateX', 'rotateY', 'rotateZ', 'translate', 'skew'];

  if (transformProps.includes(camelCase)) {
    return 'transform';
  }

  return camelCase.replace(/([A-Z])/g, '-$1').toLowerCase();
}

