/**
 * Animation Engine
 * @animation 블록 파싱 및 CSS 키프레임 생성
 *
 * 기능:
 * - @animation 블록 파싱
 * - CSS 키프레임 생성
 * - JavaScript 트리거 바인딩
 * - 타이밍 함수 지원 (ease, ease-in, ease-out, linear)
 */

class AnimationEngine {
  constructor() {
    this.animations = new Map();
    this.keyframes = new Map();
    this.triggers = new Map();
  }

  /**
   * @animation 블록 파싱
   */
  parseAnimation(name, block) {
    const animation = {
      name,
      properties: {},
      duration: 200,
      timing: 'ease-out',
      delay: 0,
      iterations: 1,
    };

    // 블록 파싱
    const lines = block.trim().split('\n');
    for (const line of lines) {
      const trimmed = line.trim();
      if (!trimmed || trimmed.startsWith('//')) continue;

      const [key, ...valueParts] = trimmed.split(':');
      const value = valueParts.join(':').trim();

      switch (key.trim()) {
        case 'duration':
          animation.duration = parseInt(value);
          break;
        case 'timing':
          animation.timing = value;
          break;
        case 'delay':
          animation.delay = parseInt(value);
          break;
        case 'iterations':
          animation.iterations = value === 'infinite' ? 'infinite' : parseInt(value);
