/**
 * Glassmorphism Engine 테스트
 */

const GlassmorphismEngine = require('./glassmorphism-engine');

let testsPassed = 0;
let testsFailed = 0;

function assertEqual(actual, expected, message) {
  if (JSON.stringify(actual) !== JSON.stringify(expected)) {
    console.error(`❌ ${message}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

function assertTrue(condition, message) {
  if (!condition) {
    console.error(`❌ ${message}`);
    testsFailed++;
    throw new Error(`Assertion failed: ${message}`);
  }
}

console.log('\n╔════════════════════════════════════════════╗');
console.log('║  Glassmorphism Engine 테스트              ║');
console.log('╚════════════════════════════════════════════╝\n');

// Test 1: @glass 블록 파싱
try {
  console.log('📝 Test 1: @glass 블록 파싱');
  const engine = new GlassmorphismEngine();

  const block = `
    background: rgba(255, 255, 255, 0.1)
    backdropFilter: blur(10px)
    border: 1px solid rgba(255, 255, 255, 0.2)

    @glass:hover
    background: rgba(255, 255, 255, 0.15)
    backdropFilter: blur(20px)
  `;

  const glass = engine.parseGlass('panel', block);

  assertTrue(glass.name === 'panel', '컴포넌트 이름');
  assertTrue(Object.keys(glass.base).length > 0, '기본 스타일');
  assertTrue(Object.keys(glass.states.hover).length > 0, 'hover 상태');

  console.log('✅ @glass 블록 파싱 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 2: Glassmorphism CSS 생성
try {
  console.log('📝 Test 2: Glassmorphism CSS 생성');
  const engine = new GlassmorphismEngine();

  engine.parseGlass('button', `
    background: rgba(255, 255, 255, 0.1)
    backdropFilter: blur(10px)
    borderRadius: 8px

    @glass:hover
    background: rgba(255, 255, 255, 0.2)
  `);

  const css = engine.generateAllStyles();

  assertTrue(css.includes('.glass-button'), 'CSS 클래스');
  assertTrue(css.includes('backdrop-filter'), 'backdrop-filter 포함');
  assertTrue(css.includes(':hover'), 'hover 상태 포함');

  console.log('✅ Glassmorphism CSS 생성 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 3: Glassmorphism 프리셋
try {
  console.log('📝 Test 3: Glassmorphism 프리셋');

  const lightPreset = GlassmorphismEngine.getPreset('light');
  const darkPreset = GlassmorphismEngine.getPreset('dark');
  const cardPreset = GlassmorphismEngine.getPreset('card');
  const buttonPreset = GlassmorphismEngine.getPreset('button');

  assertTrue(lightPreset !== undefined, 'light 프리셋');
  assertTrue(darkPreset !== undefined, 'dark 프리셋');
  assertTrue(cardPreset !== undefined, 'card 프리셋');
  assertTrue(buttonPreset !== undefined, 'button 프리셋');
  assertTrue(lightPreset.base.backdropFilter.includes('blur'), 'blur 필터');

  console.log('✅ Glassmorphism 프리셋 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 4: 다중 상태 처리
try {
  console.log('📝 Test 4: 다중 상태 처리');
  const engine = new GlassmorphismEngine();

  const block = `
    background: rgba(255, 255, 255, 0.1)

    @glass:hover
    background: rgba(255, 255, 255, 0.15)

    @glass:active
    background: rgba(255, 255, 255, 0.05)
  `;

  const glass = engine.parseGlass('interactive', block);

  assertTrue(glass.states.hover !== undefined, 'hover 상태');
  assertTrue(glass.states.active !== undefined, 'active 상태');
  assertEqual(Object.keys(glass.states).length, 2, '2개 상태');

  console.log('✅ 다중 상태 처리 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

// Test 5: CSS 프로퍼티 변환
try {
  console.log('📝 Test 5: CSS 프로퍼티 변환');
  const engine = new GlassmorphismEngine();

  const block = `
    backdropFilter: blur(10px)
    borderRadius: 12px
    boxShadow: 0 8px 32px
  `;

  engine.parseGlass('test', block);
  const css = engine.generateAllStyles();

  assertTrue(css.includes('backdrop-filter'), 'camelCase 변환');
  assertTrue(css.includes('border-radius'), 'borderRadius 변환');
  assertTrue(css.includes('box-shadow'), 'boxShadow 변환');

  console.log('✅ CSS 프로퍼티 변환 성공\n');
  testsPassed++;
} catch (err) {
  console.error(`   Error: ${err.message}\n`);
}

console.log('╔════════════════════════════════════════════╗');
console.log(`║  Test 결과: ${testsPassed}/5 통과               ║`);
console.log('╚════════════════════════════════════════════╝\n');

if (testsFailed === 0) {
  console.log('🎉 모든 테스트 통과!\n');
  process.exit(0);
} else {
  console.log(`❌ ${testsFailed}개 테스트 실패\n`);
  process.exit(1);
}
